import{R as s,e as t,f as o,U as r}from"./chunks/framework.ywem4qy5.js";const g=JSON.parse('{"title":"Formie Plugin Docs","description":"","frontmatter":{},"headers":[],"relativePath":"README.md","filePath":"README.md","lastUpdated":1778045935000}'),i={name:"README.md"};function n(a,e,l,d,c,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="formie-plugin-docs" tabindex="-1">Formie Plugin Docs <a class="header-anchor" href="#formie-plugin-docs" aria-label="Permalink to &quot;Formie Plugin Docs&quot;">​</a></h1><p>Formie’s docs are structured to help you install the plugin, build forms, put them on the site, style them, connect them to other systems, and extend them when needed.</p><h2 id="screenshot-automation" tabindex="-1">Screenshot automation <a class="header-anchor" href="#screenshot-automation" aria-label="Permalink to &quot;Screenshot automation&quot;">​</a></h2><p>Screenshots are generated with <strong><code>@verbb/docs-screenshots</code></strong>, the published npm package for Craft CP screenshot automation. This docs package depends on it in <strong>devDependencies</strong> and exposes it as <strong><code>npm run docs:screenshots</code></strong> (run that from the <strong>Formie plugin root</strong> — the directory that contains the plugin’s main <code>composer.json</code> and the npm script that invokes this docs workspace).</p><p>The harness creates its own disposable Craft install and database. Point it at a dedicated database server with <strong><code>CRAFT_SCREENSHOT_DB_*</code></strong> environment variables, then install the browser binary once with <strong><code>npx playwright install chromium</code></strong>.</p><p><strong>Layout</strong></p><ul><li><strong><code>@verbb/docs-screenshots</code></strong> — CLI and shared capture tooling (see the package’s own README on npm for flags and behaviour).</li><li><strong>Formie</strong> — one <strong><code>.screenshot.ts</code> scenario</strong> beside each page it illustrates (for example <code>forms/form-builder.screenshot.ts</code>), plus plugin-local bootstrap and fixtures under <strong><code>.screenshots/</code></strong> (Formie-specific helpers under <strong><code>.screenshots/formie/</code></strong>). Generated assets land under <strong><code>_screenshots/</code></strong> in this docs tree.</li></ul><p><strong>Typical workflow</strong></p><ol><li><code>npm run docs:screenshots -- prepare</code></li><li><code>npm run docs:screenshots -- preview --reuse-install last --filter form-builder</code></li><li>Adjust the scenario while the preview overlay shows the capture region.</li><li><code>npm run docs:screenshots -- capture --reuse-install last --filter form-builder</code></li></ol><p><strong>Useful flags</strong> (see upstream docs for the full set)</p><ul><li><code>--preview &lt;id&gt;</code> — headed preview with capture overlay.</li><li><code>--inspect &lt;id&gt;</code> — preview and pause in Playwright Inspector.</li><li><code>--headed</code> — visible browser without extra debug behaviour.</li><li><code>--save-from-preview</code> — persist framing from preview to the scenario output path.</li><li><code>--reuse-install last</code> — skip Craft bootstrap; reuse the latest prepared install.</li><li><code>--keep-install</code> — keep the temporary install for manual reuse.</li></ul><p><strong>List scenario ids</strong> (from the root of <strong>this</strong> VitePress site — the folder that contains this <code>README.md</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;id:&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;*.screenshot.ts&quot;</span></span></code></pre></div><h2 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h2><ul><li><a href="/get-started/installation-setup">Get Started</a> for installation, requirements, configuration, troubleshooting, and upgrading.</li><li><a href="/forms/form-builder">Forms</a> for building forms, configuring behavior, spam protection, <a href="/forms/submission-screening">submission screening</a>, and setting up notifications.</li><li><a href="/submissions/overview">Submissions</a> for understanding saved records, statuses, exports, relations, and editing patterns.</li><li><a href="/fields/address">Fields</a> for choosing field types and understanding the settings that actually affect behavior.</li><li><a href="/templates/rendering-forms">Templates</a> for Twig and Craft implementation patterns.</li><li><a href="/theming/overview">Theming</a> for theme config, overrides, and custom rendering.</li><li><a href="/frontend/frontend-assets">Frontend</a> for frontend packages, cached forms, and tracking patterns.</li><li><a href="/graphql/query-forms">GraphQL</a> for headless querying and submission workflows.</li><li><a href="/getting-elements/form-queries">Getting Elements</a> for form and submission queries.</li><li><a href="/integrations/address-providers/">Integrations</a> for provider families and setup patterns.</li><li><a href="/developers/events/form-events">Developers</a> for extension points, events, and command-line tooling.</li><li><a href="/reference/form">Reference</a> for the core public objects most template authors work with.</li><li><a href="/migrations/migrating-from-freeform">Migrations</a> for moving from other form plugins.</li></ul>',15)])])}const u=s(i,[["render",n]]);export{g as __pageData,u as default};
